import {publicListing} from './nextjs-administration.mjs';
export const directoryListings=[publicListing,{id:'melbourne-freedivers',name:'Melbourne Freedivers',category:'Club',state:'VIC',country:'Australia',locality:'Melbourne',description:'Local freediving and buddy training.',managed:true},{id:'coastal-folk',name:'Coastal Folk',category:'Group',state:'NSW',country:'Australia',locality:'Bondi',description:'Community water sessions.',managed:false}];
export function directoryResponse(params){const rows=directoryListings.filter(row=>['q','category','state','locality'].every(key=>{const value=params.get(key);return !value||(key==='q'?row.name.toLowerCase().includes(value.toLowerCase()):key==='locality'?row.locality.toLowerCase().includes(value.toLowerCase()):row[key]===value);})),offset=Math.max(0,Number(params.get('offset'))||0),limit=2;return {listings:rows.slice(offset,offset+limit),next:offset+limit<rows.length?offset+limit:null};}
